T={1:(2,-1),2:(3,-1),3:(2,1),5:(2,1),6:(5,1)}  # L, terminal offset relative to last stub cell (dr*1, dc)
DIR={1:(0,1),2:(0,-1),3:(1,0),5:(1,0),6:(-1,0)}

def f(g):
    H,W=len(g),len(g[0])
    seeds=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]]
    out=[row[:] for row in g]
    claims=defaultdict(set); stroke=[]
    for r,c,v in seeds:
        L,to=DIR[v]; dr=(0 if v in (1,2) else (1 if v in (3,5,6) else -1)); dc=(1 if v==1 else (-1 if v==2 else 0))
        for k in range(1,L+1):
            rr=r+dr*k; cc=c+dc*k
            if 0<=rr<H and 0<=cc<W and g[rr][cc]==0: claims[(rr,cc)].add(v); stroke.append((rr,cc,False))
        tr=r+dr*(L+1); tc=c+dc*(L+1)
        if 0<=tr<H and 0<=tc<W and g[tr][tc]==0: claims[(tr,tc)].add(v); stroke.append((tr,tc,True))
    junc={(x,y) for (x,y),vs in claims.items() if len(vs)>1}
    for (rr,cc) in stroke:
        if g[rr][cc]==0 and (rr,cc) not in junc: out[rr][cc]=5
    for j in junc: out[j[0]][j[1]]=4
    for j in junc:
        a,b=j[0]+1,j[1]-1
        while a<H and b>=0: out[a][b]=4; a+=1; b-=1
    # terminals: painted only where they were claimed and are still background or over a junction?
    for (rr,cc) in list(claims):
        vs=claims[(rr,cc)]
        if len(vs)==1:
            out[rr][cc]=list(vs)[0]
    return out
